// Prints the sparkDash Quality suite as JSON, generated by sparkDash's own qualitySuite.js inside the sparkDash
// container (read-only), for tools/memelint_suite.py. A long item's prompt is only its instruction: the haystack is
// data, rebuilt by sparkDash on each run, and haystackChars is where the instruction starts.
// env: LONG (sizes, default the r3.1 run's 8k-256k), LONG_ITEMS (default 2)
import { generateSuite, buildLongPrompt } from "/app/server/collectors/qualitySuite.js";
import { QUALITY_CATEGORIES } from "/app/src/shared/qualityBench.js";
const env = process.env;
const LONG_SPLIT = "\n\nSome codes were corrected later in the text;";
const longSizes = (env.LONG || "8192,16384,32768,65536,131072,262144").split(",").filter(Boolean).map(Number);
const items = generateSuite({ categories: QUALITY_CATEGORIES, longSizes, longItems: Number(env.LONG_ITEMS || 2) });
const out = items.map((it) => {
  const row = { id: it.id, category: it.category, thinking: it.thinking, maxTokens: it.maxTokens };
  if (it.category === "long") {
    const full = buildLongPrompt(it);
    const at = full.lastIndexOf(LONG_SPLIT);
    if (at < 0) throw new Error(`${it.id}: no instruction after the haystack`);
    row.prompt = full.slice(at + 2);
    row.haystackChars = at + 2;
  } else row.prompt = it.prompt;
  if (it.rules) row.rules = it.rules;
  return row;
});
process.stdout.write(JSON.stringify(out));
